function sprDraw(x, name, f, cx, cy, w, ang, flip, alpha, hh){
  if(!FXA.ok || !x.drawImage) return false; const fr = FXA.m[name]; if(!fr) return false;
  const r = fr[clamp(f|0, 0, fr.length-1)], h = hh || w*r[3]/r[2];
  x.save(); x.translate(cx, cy); if(ang) x.rotate(ang); if(flip) x.scale(-1, 1); if(alpha != null) x.globalAlpha = alpha; x.imageSmoothingEnabled = true;
  x.drawImage(FXA.img, r[0], r[1], r[2], r[3], -w/2, -h/2, w, h); x.restore(); return true;
}
