function drawProjSpr(x, p, sk){
  const a = p.life/p.max, t = 1-a, sc = Math.min(1.6, p.w || 1);
  if(sk==='laser' || sk==='rail'){
    const L = Math.hypot(p.x1-p.x0, p.y1-p.y0); if(L < .05) return true; const ang = Math.atan2(p.y1-p.y0, p.x1-p.x0), th = (sk==='rail' ? .24 : .16)*sc, al = Math.min(1, a*1.6), fi = (R.now*14|0) % 2;
    sprDraw(x, sk, fi, (p.x0+p.x1)/2, (p.y0+p.y1)/2, L + th*.6, ang, false, al, th);
    sprDraw(x, sk+'_b', fi, p.x1, p.y1, th*1.8, 0, false, al);
    return true;
  }
  const S = PSPR[sk]; if(!S) return false;
  const k = S.fast ? Math.min(1, t*2.2) : t, h = S.arc || 0;
  const px = p.x0+(p.x1-p.x0)*k, py = p.y0+(p.y1-p.y0)*k - Math.sin(k*Math.PI)*h;
  const dx = p.x1-p.x0, dy = (p.y1-p.y0) - Math.cos(k*Math.PI)*Math.PI*h, ang = Math.atan2(dy, dx);
  const n = FXA.m[S.n].length, fi = (R.now*12 + (p.x0*7|0)) % n | 0;
  if(sk==='musket'){ if(t < .5) sprDraw(x, 'musket_b', t < .25 ? 0 : 1, p.x0 + dx*.06, p.y0 - .05, .3*sc, 0, dx < 0, .9*(1 - t*2)); if(k >= 1) return true; sprDraw(x, 'musket', fi % 2, px, py, S.w*sc, 0, false, 1); return true; }
  if(S.fast && k >= 1) return true;
  sprDraw(x, S.n, fi, px, py, S.w*sc, ang, false, Math.min(1, a*2 + .3));
  return true;
}
