function chestAnim(src, ready){
  const sh = document.querySelector('#ovChest .sheet'); if(!sh || !sh.querySelector) return;
  let box = document.getElementById('chestAnim'); if(!box){ box = document.createElement('div'); box.id = 'chestAnim'; box.className = 'chestanim'; box.innerHTML = '<img alt="">'; sh.insertBefore(box, sh.firstChild); }
  const g = ready || /Warlord|conquered|surrendered/.test(src||'') ? 'gold' : /slew/.test(src||'') ? 'silver' : 'bronze';
  const img = box.querySelector('img'), shakes = g==='gold' ? 14 : g==='silver' ? 10 : 7, seq = [[0,300]];
  for(let k=0;k<shakes;k++) seq.push([1 + (k%2), Math.round(190 - 120*k/Math.max(1, shakes-1))]);
  seq.push([3,200],[4,260],[5,0]);
  const T = seq.slice(0, seq.findIndex(x => x[0]===3)).reduce((a,x) => a + x[1], 0)/1000;
  MUS.sting && MUS.sting('chest', {g, T});
  sh.classList.add('opening'); sh.classList.remove('opened'); R.chestLock = performance.now() + Math.min(1300, T*1000); let i = 0;
  const done = () => { sh.classList.remove('opening'); sh.classList.add('opened'); img.src = KIT['chest_'+g+'_5']; R.chestLock = 0; R.openedAt = performance.now(); };
  const step = () => { if(!sh.classList.contains('opening')) return; const [f, ms] = seq[i]; img.src = KIT['chest_'+g+'_'+f]; if(f===3){ SFX.era && SFX.era(); } if(f===4) R.shake = Math.min(3, (R.shake||0) + 1.5); i++; if(i >= seq.length){ done(); return; } setTimeout(step, ms); };
  box.onclick = () => { if(sh.classList.contains('opening')) done(); };
  step();
}
function launchCine(then){
  const ov = document.getElementById('ovCine'); if(!ov || !ov.querySelector){ then(); return; }
  const img = ov.querySelector('img'), fl = ov.querySelector('.cflash'); ov.hidden = false; let i = 0;
  const step = () => { if(i < 7){ img.src = KIT['lift_'+i]; i++; setTimeout(step, i===1 ? 650 : 330); return; }
    fl.classList.add('on'); SFX.era && SFX.era(); setTimeout(() => { ov.hidden = true; fl.classList.remove('on'); then(); }, 700); };
  step();
}
